//! Sort keys (LCMapString's LCMAP_SORTKEY), in Windows NT's format, from Microsoft's published
//! sorting weight table for Windows NT 4.0 to Windows Server 2003 ([`weights`], generated by
//! scripts/gen-sortkeys.py).
//!
//! Each character has four weights: a script member and an alphabetic weight (together its
//! Unicode weight), a diacritic weight and a case weight. A key is five sections, each but the
//! last ended by 0x01, the key by 0x00:
//!
//! - the Unicode weights, two bytes a character;
//! - the diacritic weights, a byte a character, the minimum (2) trimmed from the end; a nonspacing
//!   mark adds its diacritic weight to the character before it instead of being one (é and e +
//!   U+0301 weigh the same); the French locales write them from the string's end;
//! - the case weights, likewise trimmed (2 is lower case; 0x10 marks upper case, 0x01 full width,
//!   0x20 hiragana);
//! - the extra weights, which only the East Asian scripts have, empty here;
//! - the special weights: under the word sort (the default), punctuation is left out of the Unicode
//!   weights and written here as its position in the string (`(position << 2) | 0x8003`,
//!   big-endian, never a 0 or 1 byte) and its Unicode weight; SORT_STRINGSORT sorts it as a symbol
//!   instead.
//!
//! An expansion (æ, the ligatures) weighs as the characters it stands for; an unsortable character
//! (a control, NUL) weighs nothing. NORM_IGNORECASE, NORM_IGNOREWIDTH and NORM_IGNOREKANATYPE drop
//! their bits from the case weights, NORM_IGNORENONSPACE the diacritic weights, and
//! NORM_IGNORESYMBOLS the punctuation and symbols altogether.
//!
//! Covered: the default table's weights for Latin, IPA, the spacing and combining marks, Greek,
//! Cyrillic, Armenian, Latin Extended Additional, Greek Extended, the general punctuation, the
//! currency and letterlike symbols and the halfwidth and fullwidth forms, its expansions, and the
//! French locales' reversed diacritics. Not covered: the other scripts (a character outside the
//! table weighs nothing), the ideographs' and Hangul's multiple weights, and the locales' own
//! compressions and exceptions (the Czech "ch", the Danish "aa"...), which sort as the default.

mod weights;

/// The script members with a meaning of their own.
const UNSORTABLE: u8 = 0;
const NONSPACE_MARK: u8 = 1;
const PUNCTUATION: u8 = 6;
const SYMBOL_LAST: u8 = 11;

/// The minimum diacritic and case weight, which the key trims from its sections' ends.
const MIN_WEIGHT: u8 = 2;

/// The NORM_ flags and SORT_STRINGSORT, as the key reads them.
pub const NORM_IGNORECASE: u32 = 0x1;
pub const NORM_IGNORENONSPACE: u32 = 0x2;
pub const NORM_IGNORESYMBOLS: u32 = 0x4;
pub const NORM_IGNOREKANATYPE: u32 = 0x1_0000;
pub const NORM_IGNOREWIDTH: u32 = 0x2_0000;
pub const SORT_STRINGSORT: u32 = 0x1000;

/// The case weight's bits the flags drop.
const CASE_UPPER: u8 = 0x10;
const CASE_WIDTH: u8 = 0x01;
const CASE_HIRAGANA: u8 = 0x20;

/// A character's weights: script member, alphabetic, diacritic, case.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Weight {
    pub script: u8,
    pub alpha: u8,
    pub diacritic: u8,
    pub case: u8,
}

/// `unit`'s weights in the default table; none for a character the table leaves out (unsortable).
pub fn weight(unit: u16) -> Option<Weight> {
    let at = weights::FIRST
        .partition_point(|&first| first <= unit)
        .checked_sub(1)?;
    let first = weights::FIRST[at];
    let [length, script, alpha, diacritic, case] = weights::RUNS[at];
    let offset = unit - first;
    (offset < u16::from(length)).then(|| Weight {
        script,
        alpha: alpha + offset as u8,
        diacritic,
        case,
    })
}

/// The two characters an expansion stands for.
fn expansion(unit: u16) -> Option<(u16, u16)> {
    let at = weights::EXPANSIONS
        .binary_search_by_key(&unit, |&(from, ..)| from)
        .ok()?;
    let (_, first, second) = weights::EXPANSIONS[at];
    Some((first, second))
}

/// Whether `unit` is a nonspacing mark (NORM_IGNORENONSPACE drops it from a mapped string).
pub fn is_nonspacing(unit: u16) -> bool {
    weight(unit).is_some_and(|w| w.script == NONSPACE_MARK)
}

/// Whether `unit` is punctuation or a symbol (NORM_IGNORESYMBOLS drops it from a mapped string).
pub fn is_symbol(unit: u16) -> bool {
    weight(unit).is_some_and(|w| (PUNCTUATION..=SYMBOL_LAST).contains(&w.script))
}

/// Whether a locale writes its diacritic weights from the string's end (French's).
pub fn reverses_diacritics(lcid: u32) -> bool {
    weights::REVERSE_DIACRITICS.contains(&(lcid & 0xFFFF))
}

/// One character's entry in the Unicode, diacritic and case sections.
pub type Element = Weight;

/// A punctuation character's special weight: its position's two bytes, its script member and
/// alphabetic weight.
pub type Special = [u8; 4];

/// The string `units` weighed under `flags`: its elements, in order, to `element`, and its
/// punctuation's special weights to `special`.
pub fn weigh(
    flags: u32,
    units: impl Iterator<Item = u16>,
    mut element: impl FnMut(Element),
    mut special: impl FnMut(Special),
) {
    let mut case_mask = !0u8;
    if flags & NORM_IGNORECASE != 0 {
        case_mask &= !CASE_UPPER;
    }
    if flags & NORM_IGNOREWIDTH != 0 {
        case_mask &= !CASE_WIDTH;
    }
    if flags & NORM_IGNOREKANATYPE != 0 {
        case_mask &= !CASE_HIRAGANA;
    }
    // The element waiting for the marks after it.
    let mut pending: Option<Element> = None;
    for (index, unit) in units.enumerate() {
        let position = index as u32 + 1;
        let mut expanded = [unit, 0, 0];
        let mut count = 1;
        // An expansion's characters, an expansion's own expanded in turn (ﬃ is f, f, i).
        while let Some((first, second)) = expansion(expanded[count - 1]) {
            if count == 3 {
                break;
            }
            expanded[count - 1] = first;
            expanded[count] = second;
            count += 1;
        }
        for &unit in &expanded[..count] {
            let Some(w) = weight(unit) else { continue };
            match w.script {
                UNSORTABLE => {}
                NONSPACE_MARK => {
                    if let Some(base) = pending.as_mut() {
                        base.diacritic = base.diacritic.saturating_add(w.diacritic);
                    }
                }
                PUNCTUATION..=SYMBOL_LAST if flags & NORM_IGNORESYMBOLS != 0 => {}
                PUNCTUATION if flags & SORT_STRINGSORT == 0 => {
                    let at = ((position << 2) | 0x8003) as u16;
                    let [high, low] = at.to_be_bytes();
                    special([high, low, w.script, w.alpha]);
                }
                _ => {
                    if let Some(done) = pending.take() {
                        element(done);
                    }
                    pending = Some(Weight {
                        case: w.case & case_mask,
                        ..w
                    });
                }
            }
        }
    }
    if let Some(done) = pending {
        element(done);
    }
}

/// The sort key's bytes, to `out`: the elements' sections and the special weights (see the module
/// notes), the diacritic weights dropped for NORM_IGNORENONSPACE and reversed when `reverse`.
pub fn assemble(
    flags: u32,
    reverse: bool,
    elements: &[Element],
    specials: &[Special],
    mut out: impl FnMut(u8),
) {
    for e in elements {
        out(e.script);
        out(e.alpha);
    }
    out(1);
    if flags & NORM_IGNORENONSPACE == 0 {
        let diacritics = elements.iter().map(|e| e.diacritic);
        if reverse {
            trimmed(diacritics.rev(), &mut out);
        } else {
            trimmed(diacritics, &mut out);
        }
    }
    out(1);
    trimmed(elements.iter().map(|e| e.case), &mut out);
    out(1);
    out(1);
    specials.iter().flatten().for_each(|&byte| out(byte));
    out(0);
}

/// `weights` with the minimum trimmed from their end.
fn trimmed(weights: impl Iterator<Item = u8>, out: &mut impl FnMut(u8)) {
    let mut held = 0;
    for weight in weights {
        if weight == MIN_WEIGHT {
            held += 1;
            continue;
        }
        (0..held).for_each(|_| out(MIN_WEIGHT));
        held = 0;
        out(weight);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn key(flags: u32, lcid: u32, text: &[u16]) -> Vec<u8> {
        let (mut elements, mut specials, mut out) = (Vec::new(), Vec::new(), Vec::new());
        weigh(
            flags,
            text.iter().copied(),
            |e| elements.push(e),
            |s| specials.push(s),
        );
        assemble(
            flags,
            reverses_diacritics(lcid),
            &elements,
            &specials,
            |b| out.push(b),
        );
        out
    }

    fn utf16(text: &str) -> Vec<u16> {
        text.encode_utf16().collect()
    }

    /// The locale fixture's lcmap block's keys.
    #[test]
    fn the_captured_keys() {
        let cases: &[(u32, u32, &[u16], &[u8])] = &[
            (
                0,
                0x409,
                &utf16("abc"),
                &[14, 2, 14, 9, 14, 10, 1, 1, 1, 1, 0],
            ),
            (
                0,
                0x409,
                &utf16("ABC"),
                &[14, 2, 14, 9, 14, 10, 1, 1, 0x12, 0x12, 0x12, 1, 1, 0],
            ),
            (
                NORM_IGNORECASE,
                0x409,
                &utf16("ABC"),
                &[14, 2, 14, 9, 14, 10, 1, 1, 1, 1, 0],
            ),
            (0, 0x409, &[0xE9], &[14, 0x21, 1, 14, 1, 1, 1, 0]),
            (
                NORM_IGNORENONSPACE,
                0x409,
                &[0xE9],
                &[14, 0x21, 1, 1, 1, 1, 0],
            ),
            (0, 0x409, &utf16("e"), &[14, 0x21, 1, 1, 1, 1, 0]),
            (
                0,
                0x409,
                &utf16("co-op"),
                &[
                    14, 10, 14, 0x7C, 14, 0x7C, 14, 0x7E, 1, 1, 1, 1, 0x80, 0x0F, 6, 0x82, 0,
                ],
            ),
            (
                SORT_STRINGSORT,
                0x409,
                &utf16("co-op"),
                &[14, 10, 14, 0x7C, 6, 0x82, 14, 0x7C, 14, 0x7E, 1, 1, 1, 1, 0],
            ),
            (
                NORM_IGNORESYMBOLS,
                0x409,
                &utf16("co-op"),
                &[14, 10, 14, 0x7C, 14, 0x7C, 14, 0x7E, 1, 1, 1, 1, 0],
            ),
            (0, 0x409, &[], &[1, 1, 1, 1, 0]),
            (0, 0x40C, &[0xE9], &[14, 0x21, 1, 14, 1, 1, 1, 0]),
        ];
        for &(flags, lcid, text, expected) in cases {
            assert_eq!(key(flags, lcid, text), expected, "{text:04X?} {flags:#x}");
        }
    }

    /// A combining mark weighs as the precomposed letter does; an expansion as its letters; the
    /// French locales reverse the diacritics; the trimming keeps an inner minimum.
    #[test]
    fn marks_expansions_and_french() {
        assert_eq!(key(0, 0x409, &[0x65, 0x301]), key(0, 0x409, &[0xE9]));
        assert_eq!(key(0, 0x409, &[0xE6]), key(0, 0x409, &utf16("ae")));
        assert_eq!(key(0, 0x409, &[0xFB03]), key(0, 0x409, &utf16("ffi")));
        let (cote, french) = (&[0x63, 0xF4, 0x74, 0xE9][..], 0x40C);
        let english = key(0, 0x409, cote);
        let reversed = key(0, french, cote);
        assert_eq!(english[8..14], [1, 2, 0x12, 2, 0x0E, 1]);
        assert_eq!(reversed[8..13], [1, 0x0E, 2, 0x12, 1]);
        assert_eq!(weight(0x41).unwrap().case, 0x12);
        assert_eq!(weight(0xFF21).unwrap().case, 0x13);
        assert_eq!(weight(0x4E2D), None, "the ideographs are not covered");
        assert!(is_nonspacing(0x301) && !is_nonspacing(0x65));
        assert!(is_symbol(b'-' as u16) && is_symbol(b' ' as u16) && !is_symbol(b'a' as u16));
    }
}
